SELECT count(*) FROM profiles l JOIN profiles r ON l."key" < r."key" AND (((l.needs_resolution OR r.needs_resolution) AND (l.name = r.name)) OR ((l.needs_resolution OR r.needs_resolution) AND (l.address = r.address)) OR ((l.needs_resolution OR r.needs_resolution) AND (substr(l.name, 1, 3) = substr(r.name, 1, 3))) OR ((l.needs_resolution OR r.needs_resolution) AND (substr(l.name, 1, 1) = substr(r.name, 1, 1) AND substr(regexp_extract(l.name, '[a-z]+$'), 1, 2) = substr(regexp_extract(r.name, '[a-z]+$'), 1, 2) AND regexp_extract(l.name, '[a-z]+$') NOT IN ('limited', 'ltd', 'plc', 'llp', 'company', 'inc', 'and'))) OR ((l.needs_resolution OR r.needs_resolution) AND list_has_any(l.blocking_keys, r.blocking_keys)));
